import numpy as np
from scipy import stats, optimize
from analyze import data, segments

for check in ["bureau", "income", "bank"]:
    print(f"================ {check.upper()} ================")
    # Test multiple families via joint MLE over 6 locations + distribution params
    families = []

    # 1. Normal
    def nll_norm(p):
        locs, scale = p[:6], np.exp(p[6])
        return -sum(np.sum(stats.norm.logpdf(data[check][s], loc=locs[i], scale=scale)) for i, s in enumerate(segments))
    init_locs = [np.median(data[check][s]) for s in segments]
    r = optimize.minimize(nll_norm, init_locs + [np.log(40.0)], method="BFGS")
    families.append(("Normal", r.fun, 7, r.x[:6], f"scale={np.exp(r.x[6]):.2f}"))

    # 2. Laplace
    def nll_laplace(p):
        locs, scale = p[:6], np.exp(p[6])
        return -sum(np.sum(stats.laplace.logpdf(data[check][s], loc=locs[i], scale=scale)) for i, s in enumerate(segments))
    r = optimize.minimize(nll_laplace, init_locs + [np.log(40.0)], method="Nelder-Mead", options={'maxiter': 10000})
    families.append(("Laplace", r.fun, 7, r.x[:6], f"scale={np.exp(r.x[6]):.2f}"))

    # 3. Logistic
    def nll_logistic(p):
        locs, scale = p[:6], np.exp(p[6])
        return -sum(np.sum(stats.logistic.logpdf(data[check][s], loc=locs[i], scale=scale)) for i, s in enumerate(segments))
    r = optimize.minimize(nll_logistic, init_locs + [np.log(30.0)], method="BFGS")
    families.append(("Logistic", r.fun, 7, r.x[:6], f"scale={np.exp(r.x[6]):.2f}"))

    # 4. Cauchy (t with df=1)
    def nll_cauchy(p):
        locs, scale = p[:6], np.exp(p[6])
        return -sum(np.sum(stats.cauchy.logpdf(data[check][s], loc=locs[i], scale=scale)) for i, s in enumerate(segments))
    r = optimize.minimize(nll_cauchy, init_locs + [np.log(30.0)], method="BFGS")
    families.append(("Cauchy", r.fun, 7, r.x[:6], f"scale={np.exp(r.x[6]):.2f}"))

    # 5. Student-t (free df)
    def nll_t(p):
        locs, df, scale = p[:6], np.exp(p[6]), np.exp(p[7])
        return -sum(np.sum(stats.t.logpdf(data[check][s], df=df, loc=locs[i], scale=scale)) for i, s in enumerate(segments))
    r = optimize.minimize(nll_t, init_locs + [np.log(2.0), np.log(30.0)], method="BFGS")
    families.append(("Student-t", r.fun, 8, r.x[:6], f"df={np.exp(r.x[6]):.3f}, scale={np.exp(r.x[7]):.2f}"))

    # 6. Student-t with integer/half-integer dfs: 1.5, 2, 2.5, 3, 4, 5
    for df_fixed in [1.5, 2.0, 2.5, 3.0, 4.0]:
        def nll_tf(p, df_val=df_fixed):
            locs, scale = p[:6], np.exp(p[6])
            return -sum(np.sum(stats.t.logpdf(data[check][s], df=df_val, loc=locs[i], scale=scale)) for i, s in enumerate(segments))
        r = optimize.minimize(nll_tf, init_locs + [np.log(30.0)], method="BFGS")
        families.append((f"t(df={df_fixed})", r.fun, 7, r.x[:6], f"scale={np.exp(r.x[6]):.2f}"))

    # 7. Generalized Normal (gennorm)
    def nll_gn(p):
        locs, beta, scale = p[:6], np.exp(p[6]), np.exp(p[7])
        return -sum(np.sum(stats.gennorm.logpdf(data[check][s], beta, loc=locs[i], scale=scale)) for i, s in enumerate(segments))
    r = optimize.minimize(nll_gn, init_locs + [np.log(1.0), np.log(30.0)], method="Nelder-Mead", options={'maxiter': 10000})
    families.append(("GenNorm", r.fun, 8, r.x[:6], f"beta={np.exp(r.x[6]):.3f}, scale={np.exp(r.x[7]):.2f}"))

    families.sort(key=lambda x: 2*x[2] + 2*x[1]) # sort by AIC
    for name, nll, k, locs, extra in families[:6]:
        aic = 2*k + 2*nll
        loc_str = " ".join(f"{s}:{locs[i]:.1f}" for i, s in enumerate(segments))
        print(f"  {name:12s} | NLL={nll:6.2f} | AIC={aic:6.2f} | {extra:22s} | {loc_str}")
